name: Maintain deployed wiki
on:
  workflow_run:
    workflows: [Deploy]
    types: [completed]
    branches: [main]
  workflow_dispatch:
    inputs:
      deployment_run:
        description: 'Completed successful Deploy run to document; must be the latest successful main deployment'
        type: string
        required: true
permissions: {}
concurrency:
  group: palazzo-wiki
  cancel-in-progress: false
jobs:
  plan:
    if: >-
      github.ref == 'refs/heads/main' &&
      (github.event_name == 'workflow_dispatch' || github.event.workflow_run.conclusion == 'success')
    runs-on: ubuntu-latest
    timeout-minutes: 45
    permissions:
      contents: read
      actions: read
    outputs:
      deployment_run: ${{ steps.deployment.outputs.run }}
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.sha }}
          persist-credentials: false
      - name: Verify the successful deployed revision
        id: deployment
        uses: actions/github-script@v7
        env:
          DEPLOYMENT_RUN: ${{ github.event.workflow_run.id || inputs.deployment_run }}
        with:
          script: |
            const config = require('./.github/clouseau-wiki.json');
            const deployment = await require('./.github/scripts/wiki-deployment.cjs').resolveDeployment({
              github, context, config, runId: process.env.DEPLOYMENT_RUN});
            core.setOutput('sha', deployment.sha);
            core.setOutput('run', String(deployment.runId));
      - uses: actions/checkout@v4
        with:
          ref: ${{ steps.deployment.outputs.sha }}
          path: deployed-source
          persist-credentials: false
      - uses: actions/checkout@v4
        with:
          repository: gaulatti/clouseau
          ref: c88bb23a03c35f703f86ad1c419b80e390a07f03
          path: .clouseau-ci
          persist-credentials: false
      - uses: actions/checkout@v4
        with:
          repository: ${{ github.repository }}.wiki
          ref: master
          path: wiki
          persist-credentials: false
      - name: Generate and independently fact-check all affected pages
        uses: actions/github-script@v7
        env:
          DEEPSEEK_API_KEY: ${{ secrets.DEEPSEEK_API_KEY }}
          DEPLOYMENT_RUN: ${{ steps.deployment.outputs.run }}
        with:
          script: |
            const fs = require('node:fs');
            const config = require('./.github/clouseau-wiki.json');
            const deployment = await require('./.github/scripts/wiki-deployment.cjs').resolveDeployment({
              github, context, config, runId: process.env.DEPLOYMENT_RUN});
            fs.mkdirSync('work', {recursive: true});
            const reviews = [];
            const bundle = await require('./.clouseau-ci/src/wiki-git.cjs').prepareWiki({
              github, context: deployment, config, sourceDirectory: 'deployed-source', wikiDirectory: 'wiki',
              report: core.info, diagnostic: review => {
                reviews.push(review);
                fs.writeFileSync('work/wiki-plan.json.diagnostic.json', JSON.stringify({version: 1, reviews}, null, 2) + '\n');
              }});
            fs.writeFileSync('work/wiki-plan.json', JSON.stringify(bundle, null, 2) + '\n');
            core.info(`Validated ${bundle.updates.length} coordinated wiki pages for deployed ${deployment.sha}.`);
      - uses: actions/upload-artifact@v4
        if: always()
        with:
          name: wiki-plan-${{ github.run_id }}-${{ github.run_attempt }}
          path: work/wiki-plan.json*
          if-no-files-found: ignore
          retention-days: 7
  publish:
    needs: plan
    if: github.ref == 'refs/heads/main' && needs.plan.result == 'success'
    runs-on: ubuntu-latest
    timeout-minutes: 10
    permissions:
      contents: write
      actions: read
    steps:
      - uses: actions/checkout@v4
        with:
          ref: ${{ github.sha }}
          persist-credentials: false
      - name: Revalidate the deployment before publication
        id: deployment
        uses: actions/github-script@v7
        env:
          DEPLOYMENT_RUN: ${{ needs.plan.outputs.deployment_run }}
        with:
          script: |
            const config = require('./.github/clouseau-wiki.json');
            const deployment = await require('./.github/scripts/wiki-deployment.cjs').resolveDeployment({
              github, context, config, runId: process.env.DEPLOYMENT_RUN});
            core.setOutput('sha', deployment.sha);
      - uses: actions/checkout@v4
        with:
          ref: ${{ steps.deployment.outputs.sha }}
          path: deployed-source
          persist-credentials: false
      - uses: actions/checkout@v4
        with:
          repository: gaulatti/clouseau
          ref: c88bb23a03c35f703f86ad1c419b80e390a07f03
          path: .clouseau-ci
          persist-credentials: false
      - uses: actions/checkout@v4
        with:
          repository: ${{ github.repository }}.wiki
          ref: master
          path: wiki
          persist-credentials: true
      - uses: actions/download-artifact@v4
        with:
          name: wiki-plan-${{ github.run_id }}-${{ github.run_attempt }}
          path: wiki-plan
      - name: Publish the validated pages in one non-force wiki commit
        uses: actions/github-script@v7
        env:
          DEPLOYMENT_RUN: ${{ needs.plan.outputs.deployment_run }}
        with:
          script: |
            const fs = require('node:fs');
            const config = require('./.github/clouseau-wiki.json');
            const deployment = await require('./.github/scripts/wiki-deployment.cjs').resolveDeployment({
              github, context, config, runId: process.env.DEPLOYMENT_RUN});
            const bundle = JSON.parse(fs.readFileSync('wiki-plan/wiki-plan.json', 'utf8'));
            const result = await require('./.clouseau-ci/src/wiki-git.cjs').publishWiki({
              github, context: deployment, config, sourceDirectory: 'deployed-source', wikiDirectory: 'wiki', bundle});
            core.info(JSON.stringify({...result, deployed_sha: deployment.sha, deployment_run: deployment.runId}));

